// Settings need a name AND a description; read them via .value:
const interval = SliderSetting("Interval (s)", "How often to run, in seconds", 1, 30, 5);
const mode     = DropdownSetting("Mode", "Where to show the message", ["Chat", "Notify"], "Chat");
const fancy    = BooleanSetting("Fancy color", "Tint the notification", false);
const color    = ColorSetting("Color", "Notification tint color", 0x55FFFF);

color.visibleWhen(() => fancy.value);            // now color only shows when Fancy is on!
mode.onChange(v => script.chat("Mode is now " + v));

const mod = module.create({
    name: "My Module",
    description: "welcome world :D",
    category: "SCRIPTS",
    // define all your settings in an array here
    settings: [interval, mode, fancy, color],
    onEnable:  () => script.log("enabled"),
    onDisable: () => script.log("disabled"),
});

let ticks = 0;

// runs 20 times for example
on("tick", () => {
    if (++ticks < interval.value * 20) return;
    ticks = 0;

    const msg = "Purse: " + skyblock.purse().toLocaleString() + "  roll: " + math.randomInt(1, 100);
    if (mode.value === "Notify") notification.info("My Module", msg);
    else script.chat(msg);
});

// you can hook a LOT of other custom events :)
on("chatReceive", (text) => {
    if (text.includes("wassup")) script.chat("hi :)");
});

module.export(mod);

