// Settings need a name AND a description; read them via .value:
const delay = SliderSetting("Delay (ms)", "Pause between actions", 0, 2000, 500);

const m = macro.create({
    name: "My Macro",
    description: "A starter script macro.",
    subcategory: "Scripts",
    // define all your settings in an array here
    settings: [delay],
});

// a little HUD line shown while the macro runs
m.hud(() => "State: " + m.currentState() + "  delay: " + delay.value);

m.onEnable(() => {
    script.log("macro enabled");
    m.setState("MOVE");
});

// macros are state machines — onState runs each tick while in that state
m.onState("MOVE", () => {
    // do your thing, then switch states with m.setState("KILL"), etc.
});

m.onDisable(() => script.log("macro disabled"));

macro.export(m);

